declare_rule! {
    /// Disallow the use of barrel file.
    ///
    /// A barrel file is a file that re-exports all of the exports from other files in a directory.
    /// This structure results in the unnecessary loading of many modules, significantly impacting performance in large-scale applications.
    /// Additionally, it complicates the codebase, making it difficult to navigate and understand the project's dependency graph.
    /// This rule ignores .d.ts files and type-only exports.
    ///
    /// For a more detailed explanation, check out https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-7/
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// export * from "foo";
    /// export * from "bar";
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// export { foo } from "foo";
    /// export { bar } from "bar";
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// export { default as module1 } from "./module1";
    /// export { default as module2 } from "./module2";
    /// ```
    ///
    /// ### Valid
    ///
    /// ```ts
    /// export type * from "foo";
    /// export type { foo } from "foo";
    /// ```
    ///
    pub NoBarrelFile {
        version: "next",
        name: "noBarrelFile",
        recommended: false,
        source: RuleSource::EslintBarrelFiles("avoid-barrel-files"),
        source_kind: RuleSourceKind::Inspired,
    }
}

impl Rule for NoBarrelFile {
    type Query = Ast<JsExport>;
    type State = TextRange;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let export = ctx.query();
        if let Ok(export_clause) = export.export_clause() {
            let need_diagnostic = match export_clause {
                AnyJsExportClause::JsExportFromClause(node) => node.type_token().is_none(),
                AnyJsExportClause::JsExportNamedFromClause(node) => node.type_token().is_none(),
                _ => false,
            };
            if need_diagnostic {
                return Some(export.syntax().text_trimmed_range());
            }
        }
        None
    }

    fn diagnostic(_ctx: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                range,
                markup! {
                    "Avoid barrel files, they slow down performance, and cause large module graphs with modules that go unused."
                },
            )
            .note(markup! {
                "Check this "<Hyperlink href="https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-7/">"thorough explanation"</Hyperlink>" to better understand the context."
            }),
        )
    }
}
