8	declare_rule! {
9	    /// Disallow the use of barrel file.
10	    ///
11	    /// A barrel file is a file that re-exports all of the exports from other files in a directory.
12	    /// This structure results in the unnecessary loading of many modules, significantly impacting performance in large-scale applications.
13	    /// Additionally, it complicates the codebase, making it difficult to navigate and understand the project's dependency graph.
14	    /// This rule ignores .d.ts files and type-only exports.
15	    ///
16	    /// For a more detailed explanation, check out https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-7/
17	    ///
18	    /// ## Examples
19	    ///
20	    /// ### Invalid
21	    ///
22	    /// ```js,expect_diagnostic
23	    /// export * from "foo";
24	    /// export * from "bar";
25	    /// ```
26	    ///
27	    /// ```js,expect_diagnostic
28	    /// export { foo } from "foo";
29	    /// export { bar } from "bar";
30	    /// ```
31	    ///
32	    /// ```js,expect_diagnostic
33	    /// export { default as module1 } from "./module1";
34	    /// export { default as module2 } from "./module2";
35	    /// ```
36	    ///
37	    /// ### Valid
38	    ///
39	    /// ```ts
40	    /// export type * from "foo";
41	    /// export type { foo } from "foo";
42	    /// ```
43	    ///
44	    pub NoBarrelFile {
45	        version: "next",
46	        name: "noBarrelFile",
47	        recommended: false,
48	        source: RuleSource::EslintBarrelFiles("avoid-barrel-files"),
49	        source_kind: RuleSourceKind::Inspired,
50	    }
51	}
